import static com.erni.finalanswer.audio.LastCommandAudio.Cue.*;
/** Device-independent event, authority, priority, mix and lifecycle regression. */
public final class LastCommandAudioCheck {
 static void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
 static class Fake implements InvocationHandler {int plays,stops,disposed;boolean playing;float level;long next=1;public Object invoke(Object p,Method m,Object[] a){switch(m.getName()){case "play"->{plays++;playing=true;if(a!=null&&a.length>0)level=(float)a[0];if(m.getReturnType()==long.class)return next++;}case "stop","pause"->{stops++;playing=false;}case "dispose"->disposed++;case "isPlaying"->{return playing;}case "setVolume"->level=(float)a[a.length-1];}if(m.getReturnType()==boolean.class)return false;if(m.getReturnType()==long.class)return 0L;if(m.getReturnType()==float.class)return 0f;if(m.getReturnType()==int.class)return 0;return null;}<T>T proxy(Class<T> c){return c.cast(Proxy.newProxyInstance(c.getClassLoader(),new Class<?>[]{c},this));}}
 static JsonObject panel(String task,String feedback,int score,long next){return JsonParser.parseString("{sessionId:'s',sequence:1,lever:'UP',adjuster:0,hatch:false,code:'0000',held:[],lastAction:{},testRound:{expanded:true,campaign:true,status:'PLAYING',taskId:'"+task+"',taskType:'ADJUSTER',attemptId:'a',step:"+score+",category:'MECHANICAL',feedback:'"+feedback+"',nextAt:"+next+",readyAt:0,signals:[],touchscreen:{kind:'physical'}}}").getAsJsonObject();}
 public static void main(String[] args)throws Exception{
  Path root=Path.of(args[0]);String manifest=Files.readString(root.resolve("sounds/last_command/runtime/manifest.json"));var files=new LinkedHashMap<String,Fake>();var warnings=new ArrayList<String>();var clock=new AtomicLong(1000);var mix=new AudioMix();
  var audio=new LastCommandAudio(new PresentationAudio.Backend(){public Sound sound(String path){check(Files.exists(root.resolve(path)),path);var f=new Fake();files.put(path,f);return f.proxy(Sound.class);}public Music music(String path){check(path.endsWith("success.mp3"),"Only victory streams");var f=new Fake();files.put(path,f);return f.proxy(Music.class);}},mix,clock::get,warnings::add,manifest);
  for(var cue:LastCommandAudio.Cue.values())check(audio.available(cue),"Available "+cue);check(files.size()==26,"One load per registered cue");
  audio.play(BUTTON_PRESS,"press-1");audio.play(BUTTON_PRESS,"press-1");check(audio.playCount(BUTTON_PRESS)==1,"Held/repeated press dedup");audio.play(ROTARY_STEP,"dial-1");audio.play(ROTARY_STEP,"dial-2");check(audio.playCount(ROTARY_STEP)==1,"Rotary throttle");clock.addAndGet(100);audio.play(ROTARY_STEP,"dial-3");check(audio.playCount(ROTARY_STEP)==2,"Next detent");
  var events=new LastCommandAudioEvents(audio);
  for(var mapping:List.of(new Object[]{PanelElementId.BIG_BUTTON,PanelAction.Kind.PRESSED,"",BUTTON_PRESS},new Object[]{PanelElementId.SMALL_BUTTON_1,PanelAction.Kind.PRESSED,"",SMALL_BUTTON_CLICK},new Object[]{PanelElementId.LEVER_MODULE,PanelAction.Kind.LEVER_CHANGED,"DOWN",LEVER_MOVE},new Object[]{PanelElementId.ADJUSTER,PanelAction.Kind.ADJUSTER_CHANGED,"45",ROTARY_STEP},new Object[]{PanelElementId.CODE_PANEL,PanelAction.Kind.CODE_UPDATED,"1000",ROTARY_STEP},new Object[]{PanelElementId.HIDDEN_HATCH,PanelAction.Kind.HATCH_CHANGED,"OPEN",HATCH_OPEN})){clock.addAndGet(2000);audio.update();var cue=(LastCommandAudio.Cue)mapping[3];long n=audio.playCount(cue);var action=new PanelAction(clock.get(),0,(PanelElementId)mapping[0],(PanelAction.Kind)mapping[1],(String)mapping[2],PanelAction.Cause.PLAYER);events.panel(action,clock.get());events.panel(action,clock.get());check(audio.playCount(cue)==n+1,"Native physical mapping and duplicate suppression: "+cue);}
  long hatch=audio.playCount(HATCH_OPEN);events.panel(new PanelAction(99999,0,PanelElementId.HIDDEN_HATCH,PanelAction.Kind.HATCH_CHANGED,"CLOSED",PanelAction.Cause.PLAYER),clock.get());check(audio.playCount(HATCH_OPEN)==hatch,"Closing hatch is not opening audio");
  events.snapshot(panel("t1","",0,0),1000);events.snapshot(panel("t1","COMMAND ACCEPTED",1,1700),1000);events.snapshot(panel("t1","COMMAND ACCEPTED",1,1700),1000);check(audio.playCount(ANSWER_CORRECT)==1,"Authoritative correct once");
  events.snapshot(panel("t2","",1,0),2000);events.snapshot(panel("t2","WRONG COMMAND",1,2700),2000);check(audio.playCount(ANSWER_WRONG)==1,"Authoritative wrong once; unchanged score");
  clock.addAndGet(3000);audio.update();var circuit=panel("c","",1,0);circuit.getAsJsonObject("testRound").addProperty("taskType","CIRCUIT");events.snapshot(circuit,3000);events.touch("ROTATE",3000);check(audio.playCount(CIRCUIT_ROTATE)==1,"Wire manipulation");circuit=circuit.deepCopy();circuit.getAsJsonObject("testRound").addProperty("feedback","WRONG COMMAND");circuit.getAsJsonObject("testRound").addProperty("nextAt",3700);events.snapshot(circuit,3000);check(audio.playCount(CIRCUIT_FAILED)==1,"Only validated circuit failure");
  clock.addAndGet(4000);audio.update();var done=panel("c2","",1,0);done.getAsJsonObject("testRound").addProperty("taskType","CIRCUIT");events.snapshot(done,4000);done=done.deepCopy();done.getAsJsonObject("testRound").addProperty("feedback","COMMAND ACCEPTED");done.getAsJsonObject("testRound").addProperty("nextAt",4700);events.snapshot(done,4000);check(audio.playCount(CIRCUIT_COMPLETE)==1,"Circuit complete once");
  var memory=panel("mem","",2,0);var r=memory.getAsJsonObject("testRound");r.addProperty("category","MEMORY");r.addProperty("taskType","LIGHT_MEMORY");r.addProperty("readyAt",5000);r.getAsJsonObject("touchscreen").add("flashes",JsonParser.parseString("[0,1,2,3]"));r.getAsJsonObject("touchscreen").addProperty("revealUntil",9000);events.snapshot(memory,5000);for(int i=0;i<4;i++){clock.addAndGet(850);events.frame(5000+850L*i);events.frame(5000+850L*i+16);}for(var cue:List.of(MEMORY_NOTE_RED,MEMORY_NOTE_GREEN,MEMORY_NOTE_BLUE,MEMORY_NOTE_YELLOW))check(audio.playCount(cue)==1,"One per active flash: "+cue);
  check(!audio.play(METAL_CRACK,"during-memory"),"No structural noise over memory");audio.protectedTask(false);clock.addAndGet(5000);audio.update();var won=panel("final","",19,0);events.snapshot(won,10000);long ordinary=audio.playCount(ANSWER_CORRECT);won=won.deepCopy();won.getAsJsonObject("testRound").addProperty("status","WON");won.getAsJsonObject("testRound").addProperty("step",20);won.getAsJsonObject("testRound").addProperty("finishedAt",10000);won.getAsJsonObject("testRound").addProperty("feedback","COMMAND ACCEPTED");events.snapshot(won,10000);events.snapshot(won,10000);events.frame(10700);events.frame(10716);check(audio.playCount(MACHINE_SHUTDOWN)==1&&audio.playCount(VICTORY)==1,"Existing blackout and victory once");check(audio.playCount(ANSWER_CORRECT)==ordinary,"No ordinary success on final victory");
  clock.addAndGet(5000);audio.update();long fast=audio.playCount(ANSWER_CORRECT);for(int i=0;i<4;i++){audio.play(ANSWER_CORRECT,"fast-verdict-"+i);clock.addAndGet(700);audio.update();}check(audio.playCount(ANSWER_CORRECT)==fast+4,"Rapid authoritative verdicts never dropped by same-clip cap");
  clock.addAndGet(5000);audio.update();var spoken=new ArrayList<String>();var stopped=new int[1];var extra=new LastCommandAudioEvents(audio,(id,key)->spoken.add(id),()->stopped[0]++);
  for(String color:List.of("RED","GREEN","BLUE","YELLOW")){var command=panel("voice-"+color,"",0,0);var cr=command.getAsJsonObject("testRound");cr.addProperty("taskType","FALSE_COMMAND");cr.addProperty("readyAt",20000);cr.getAsJsonObject("touchscreen").addProperty("spokenColor",color);extra.snapshot(command,19000);extra.frame(19999);int before=spoken.size();extra.frame(20000);extra.frame(20016);extra.snapshot(command,20016);extra.frame(20032);check(spoken.size()==before+1&&spoken.get(before).equals("PRESS_"+color),"Generated host template, one per task: "+color);}
  extra.pause();extra.resume();extra.frame(20048);check(spoken.size()==4,"Pause/resume cannot replay host instruction");check(stopped[0]==4,"Task changes and pause cancel owning host request");
  var symbolic=panel("symbols","",0,0);symbolic.getAsJsonObject("testRound").addProperty("taskType","ODD_SYMBOL");extra.snapshot(symbolic,21000);long appeared=audio.playCount(SYMBOL_APPEAR);extra.frame(21000);extra.frame(21016);check(audio.playCount(SYMBOL_APPEAR)==appeared+1,"Symbol appearance once per actual face");long clicked=audio.playCount(SYMBOL_CLICK);extra.touch("SELECT",21000);check(audio.playCount(SYMBOL_CLICK)==clicked+1,"Symbol interaction is separate");long wrong=audio.playCount(ANSWER_WRONG),symbolWrong=audio.playCount(SYMBOL_WRONG);symbolic=symbolic.deepCopy();symbolic.getAsJsonObject("testRound").addProperty("feedback","WRONG COMMAND");symbolic.getAsJsonObject("testRound").addProperty("nextAt",21700);extra.snapshot(symbolic,21000);extra.snapshot(symbolic,21000);check(audio.playCount(SYMBOL_WRONG)==symbolWrong+1&&audio.playCount(ANSWER_WRONG)==wrong,"Only authoritative symbol-specific wrong sound");
  clock.addAndGet(5000);audio.update();var hatchPanel=panel("hatch","",0,0);hatchPanel.addProperty("hatch",true);extra.snapshot(hatchPanel,22000);long closed=audio.playCount(HATCH_CLOSE);hatchPanel=hatchPanel.deepCopy();hatchPanel.addProperty("hatch",false);extra.snapshot(hatchPanel,22000);extra.frame(22000,false);check(audio.playCount(HATCH_CLOSE)==closed,"Closing begins silently");extra.frame(22500,true);extra.frame(22516,true);check(audio.playCount(HATCH_CLOSE)==closed+1,"Close sound at completed movement exactly once");
  var change=panel("change","",0,0);change.getAsJsonObject("testRound").addProperty("taskType","FIND_CHANGE");change.getAsJsonObject("testRound").addProperty("category","MEMORY");change.getAsJsonObject("testRound").getAsJsonObject("touchscreen").addProperty("revealUntil",30000);extra.snapshot(change,26000);extra.frame(26000);long transitions=audio.playCount(SCREEN_TRANSITION);extra.frame(29500);clock.addAndGet(5000);audio.update();extra.frame(30000);extra.frame(30016);check(audio.playCount(SCREEN_TRANSITION)==transitions+1,"Transition after actual Find Change blackout, not repeated frames");long confirms=audio.playCount(CONFIRM);extra.touch("CONFIRM",31000);check(audio.playCount(CONFIRM)==confirms+1,"Confirmation independent of success");
  var silent=panel("silence","",4,0);silent.getAsJsonObject("testRound").addProperty("taskType","SILENCE");events.snapshot(silent,12000);check(!audio.play(METAL_CREAK,"silence"),"No decorative noise during silence");audio.volume(0);check(!audio.play(SMALL_BUTTON_CLICK,"muted"),"Independent mute");audio.volume(1);events.pause();check(!audio.play(LEVER_MOVE,"paused"),"Pause stops and blocks");events.resume();audio.close();audio.close();for(var f:files.values())check(f.disposed==1,"Dispose each resource exactly once");check(warnings.isEmpty(),warnings.toString());System.out.println("LAST_COMMAND_AUDIO_OK: 26 cached cues, authoritative dedup, circuit outcomes, four frame-synced notes, victory/shutdown, priority/mute/pause/disposal; host template selection/cancel/dedup; symbol and hatch/transition events");
 }
}
